#!/usr/bin/env python3
"""Generate ESP Web Tools assets from the exact PlatformIO build; fail closed."""
import argparse,json,hashlib,shutil,sys
from pathlib import Path

def main():
 p=argparse.ArgumentParser();p.add_argument('--build-dir',required=True);p.add_argument('--out',required=True);p.add_argument('--version',default='0.9.7-rc4');args=p.parse_args()
 b=Path(args.build_dir);out=Path(args.out);out.mkdir(parents=True,exist_ok=True)
 # ESP32 classic standard PlatformIO/Arduino partition layout. Never assume offsets
 # without checking the partition table generated by the build.
 table=b/'partitions.bin';app=b/'firmware.bin';boot=b/'bootloader.bin'
 for f in (table,app,boot):
  if not f.is_file() or f.stat().st_size<256:sys.exit('Missing or implausible build output: '+str(f))
 try:
  from gen_esp32part import PartitionTable
 except ImportError:
  sys.exit('gen_esp32part unavailable; install matching ESP-IDF tooling or use esptool bundled with PlatformIO')
 partitions=PartitionTable.from_binary(table.read_bytes())
 factory=[p for p in partitions if p.name=='nvs']
 apps=[p for p in partitions if p.type==0 and p.subtype in (0,16)]
 if not factory or not apps:sys.exit('Expected NVS and factory/OTA app partition not found')
 nvs=factory[0];target=apps[0]
 if target.offset!=0x10000:sys.exit('Unexpected app offset; requires human review: '+hex(target.offset))
 if nvs.offset!=0x9000:sys.exit('Unexpected NVS offset; requires human review: '+hex(nvs.offset))
 if app.stat().st_size>target.size:sys.exit('Firmware exceeds app partition')
 # Bootloader offset and boot_app0 depend on framework/flash layout. Do not infer.
 # For the public web installer use app-only upgrade, preserving NVS. First-time
 # installation requires factory image validation and is deliberately not enabled.
 name='firmware.bin';shutil.copyfile(app,out/name)
 manifest={'name':'CYD YouTube Dashboard (existing device upgrade ONLY)','version':args.version,'builds':[{'chipFamily':'ESP32','parts':[{'path':name,'offset':target.offset}]}]}
 (out/'manifest-upgrade.json').write_text(json.dumps(manifest,indent=2)+'\n')
 (out/'SHA256SUMS.txt').write_text(hashlib.sha256(app.read_bytes()).hexdigest()+'  '+name+'\n')
 print('APP ONLY / PRESERVES NVS; this is NOT a factory installer')
 print('NVS:',hex(nvs.offset),hex(nvs.size),'APP:',hex(target.offset),hex(target.size))
if __name__=='__main__':main()
